parameters.jsCode:
// Parse hasil JSON dari Ollama Lokal dengan Safeguard 40-45 Detik (105-120 kata)
const inputData = $input.first().json;
let parsed = {};

try {
  let rawText = "";
  if (inputData.response) {
    rawText = inputData.response;
  } else if (typeof inputData === "string") {
    rawText = inputData;
  }

  rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {};
}

const topicMeta = $('2b. Format Parameter Topik').first().json;
const keyword = topicMeta.lead_magnet_keyword || 'ALUR';
const topicTitle = topicMeta.topik || 'Otomasi Bisnis dengan n8n';

// Fallback naskah standar 105 kata jika parsing gagal atau teks kosong
const standardScript = `Tahukah Anda bahwa banyak bisnis boncos jutaan rupiah setiap bulan hanya untuk bayar software otomatisasi mahal dan gaji lembur karyawan? Padahal di era modern sekarang, Anda bisa membangun alur otomatisasi mandiri yang jauh lebih canggih tanpa biaya langganan sepeserpun! Caranya adalah dengan memasang n8n di laptop atau server lokal Anda sendiri. Dengan n8n, Anda bisa menghubungkan WhatsApp, Google Sheets, dan database kantor tanpa batasan kuota. Seluruh data rahasia perusahaan tetap aman di internal dan tidak bocor ke pihak luar. Komen ${keyword} di bawah sekarang juga, saya kirimkan file JSON workflow dan panduan instalasi lengkapnya gratis ke inbox Anda! Like dan subscribe sekarang!`;

let finalScript = (parsed.full_voiceover_script || '').trim();

// SAFEGUARD DURASI: Jika hasil LLM < 85 kata, gunakan skrip gabungan scene atau perpanjang agar pas 40-45 detik
const wordCount = finalScript.split(/\s+/).filter(w => w.length > 0).length;
if (wordCount < 85) {
  if (parsed.scenes && parsed.scenes.length > 0) {
    const combinedChunks = parsed.scenes.map(s => s.narration_chunk || '').join(' ').trim();
    if (combinedChunks.split(/\s+/).length >= 85) {
      finalScript = combinedChunks;
    } else {
      finalScript = standardScript;
    }
  } else {
    finalScript = standardScript;
  }
}

// FORMAT DESKRIPSI SEO LENGKAP DENGAN SIGNATURE CHANNEL
const shortDesc = parsed.description || `Panduan ${topicTitle} otomatis tanpa ribet.`;
const fullSeoDescription = `${shortDesc}

Komen ${keyword} di kolom komentar sekarang juga untuk mendapatkan blueprint dan file JSON workflow lengkapnya ke inbox Anda!

📚 EBOOK & PORTOFOLIO:
"Bikin Bisnis Jalan Sendiri: Otomasi AI & n8n"
👉 https://lynk.id/simpuldigital/54g68pyd6mnw

💼 KONSULTASI & KERJASAMA:
👉 LinkedIn: https://www.linkedin.com/in/mohamad-ricky-1949b8ab/

Subscribe @mrickyit untuk update blueprint otomasi bisnis setiap minggunya!

#Shorts #n8n #AI #OtomasiBisnis #AIWorker #Freelancer #SoftwareEngineering`;

return [{
  json: {
    slot_id: topicMeta.slot_id,
    day: topicMeta.day,
    slot: topicMeta.slot,
    voice: topicMeta.voice,
    lead_magnet_keyword: keyword,
    video_title: parsed.title || `${topicTitle} #Shorts`,
    video_description: fullSeoDescription,
    voiceover_script: finalScript,
    scenes: parsed.scenes && parsed.scenes.length >= 4 ? parsed.scenes : [
      { scene_number: 1, duration_seconds: 8, broll_search_keyword: topicMeta.broll_search_keyword || 'business office modern', on_screen_text: 'STOP CARA LAMA', narration_chunk: '' },
      { scene_number: 2, duration_seconds: 12, broll_search_keyword: 'server hardware datacenter', on_screen_text: 'HEMAT BIAYA', narration_chunk: '' },
      { scene_number: 3, duration_seconds: 15, broll_search_keyword: 'connected nodes automation', on_screen_text: 'OTOMASI 24 JAM', narration_chunk: '' },
      { scene_number: 4, duration_seconds: 9, broll_search_keyword: 'subscribe like cta button', on_screen_text: `KOMEN ${keyword} SEKARANG`, narration_chunk: '' }
    ],
    total_scenes: 4
  }
}];

// Siapkan aset visual per scene
const inputItem = $input.first().json;
const scenes = inputItem.scenes || [];

const enrichedScenes = scenes.map((s, idx) => {
  return {
    scene_number: s.scene_number || (idx + 1),
    duration_seconds: s.duration_seconds || 8,
    broll_search_keyword: s.broll_search_keyword || "technology abstract dark",
    on_screen_text: s.on_screen_text || "AI AUTOMATION",
    narration_chunk: s.narration_chunk || "",
    style: "dark_modern_tech"
  };
});

return [{
  json: {
    slot_id: inputItem.slot_id,
    day: inputItem.day,
    slot: inputItem.slot,
    voice: inputItem.voice,
    lead_magnet_keyword: inputItem.lead_magnet_keyword,
    video_title: inputItem.video_title,
    video_description: inputItem.video_description,
    voiceover_script: inputItem.voiceover_script,
    scenes: enrichedScenes,
    total_scenes: enrichedScenes.length
  }
}];

